world node {
    use aap:caps/types@0.1.0.{heartbeat-report};

    import aap:caps/http-client@0.1.0;
    import aap:caps/notifier@0.1.0;
    import aap:caps/state-rw@0.1.0;
    import wasi:clocks/wall-clock@0.2.0;

    export run: func(feed-url: string) -> heartbeat-report;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

/// Key in the shared store under which every call records the input it received.
const LAST_INPUT_KEY: &str = "last-input";

/// How many times to offer the notification before giving up. The contract
/// requires `notified == true` on every output, so a node that cannot get its
/// notification accepted must not return a report at all.
const NOTIFY_ATTEMPTS: u32 = 3;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Approved extension: record the input this call received.
        state_rw::put(LAST_INPUT_KEY, &feed_url);

        // Clock: the time this heartbeat fired.
        let seconds = wall_clock::now().seconds;

        // HTTP: one permitted fetch. A transport failure (timeout, error
        // status, oversize body) is a value, and it counts as zero characters
        // fetched. A host outside the allowlist traps at the boundary, as the
        // capability intends.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // Notifier: the message is built only from values the node computed
        // and its own input, never from the fetched (untrusted) body.
        let message = format!(
            "heartbeat at {seconds}: fetched {fetched} characters from {feed_url}"
        );

        let mut notified = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }

        // ensures notified == true: never produce an output that violates it.
        if !notified {
            panic!("notification was not accepted; refusing to emit a report");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

